<div class="page-heading"><h1>Categories & tags</h1><p>Rename, consolidate or disable categories without breaking research relationships.</p></div><?php foreach(['categories','tags'] as $kind): ?><section><h2><?=e(ucfirst($kind))?></h2><form method="post" class="inline-form"><?=csrf()?><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="action" value="add"><?php field('New '.$kind.' name','name','','text',true); ?><button>Add</button></form><?php $rows=all("SELECT * FROM $kind ORDER BY name"); foreach($rows as $row): ?><details class="taxonomy-item"><summary><?=e($row['name'])?><?php if(isset($row['enabled'])&&!$row['enabled']): ?> (disabled)<?php endif ?></summary><div class="field-grid"><form method="post"><?=csrf()?><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><input type="hidden" name="action" value="rename"><?php field('Name','name',$row['name'],'text',true); ?><button>Rename</button></form><form method="post"><?=csrf()?><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><input type="hidden" name="action" value="merge"><?php select_field('Consolidate into','target',array_column(array_filter($rows,fn($t)=>$t['id']!==$row['id']),'name','id')); ?><label class="check"><input type="checkbox" required> Move associations and delete this label.</label><button>Consolidate</button></form><?php if($kind==='categories'): ?><form method="post"><?=csrf()?><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><input type="hidden" name="action" value="disable"><button class="secondary">Toggle availability</button></form><?php endif ?></div></details><?php endforeach ?></section><?php endforeach ?>